package com.ecommerce.order.controller;
import com.ecommerce.order.dto.OrderDtos; import com.ecommerce.order.service.OrderService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/v1/orders") public class OrderController {private final OrderService orders;public OrderController(OrderService orders){this.orders=orders;} @PostMapping @ResponseStatus(HttpStatus.CREATED) public OrderDtos.Response create(@RequestHeader("X-User-Id") Long userId,@Valid @RequestBody OrderDtos.Create request){return orders.create(userId,request);}@GetMapping public List<OrderDtos.Response> list(@RequestHeader("X-User-Id") Long userId){return orders.list(userId);}@GetMapping("/{orderId}") public OrderDtos.Response get(@RequestHeader("X-User-Id") Long userId,@PathVariable Long orderId){return orders.get(userId,orderId);}@PatchMapping("/{orderId}/cancel")public OrderDtos.Response cancel(@RequestHeader("X-User-Id") Long userId,@PathVariable Long orderId){return orders.cancel(userId,orderId);}@PatchMapping("/{orderId}/status")public OrderDtos.Response transition(@PathVariable Long orderId,@Valid @RequestBody OrderDtos.Transition request){return orders.transition(orderId,com.ecommerce.order.entity.OrderStatus.valueOf(request.status().trim().toUpperCase()));}}
